{
  "root_cause": "The tabbable library (src/index.js) contains an invalid CSS selector 'details>summary:first-of-type' in its candidateSelectors array and in the isHidden function. When the focus trap calls tabbable(container), it invokes querySelectorAll with a selector list that includes this invalid pseudo-class, causing a DOMException. This prevents the focus trap from computing tabbable nodes and moving initial focus into the dialog.",
  "repair_strategy": "Replace the invalid selector 'details>summary:first-of-type' with the valid CSS selector 'details>summary:first-child' in both occurrences within src/index.js. This allows querySelectorAll to succeed and the focus trap to find the first tabbable element (#street).",
  "edits": [
    {
      "path": "src/index.js",
      "sha256": "8f69e239e7365811abad1130954bb9d4772c0f0e31c477f37f22a3644de78652",
      "before": "const candidateSelectors = [
  'input',
  'select',
  'textarea',
  'a[href]',
  'button',
  '[tabindex]',
  'audio[controls]',
  'video[controls]',
  '[contenteditable]:not([contenteditable="false"])',
  'details>summary:first-of-type',
  'details',
];",
      "after": "const candidateSelectors = [
  'input',
  'select',
  'textarea',
  'a[href]',
  'button',
  '[tabindex]',
  'audio[controls]',
  'video[controls]',
  '[contenteditable]:not([contenteditable="false"])',
  'details>summary:first-child',
  'details',
];"
    },
    {
      "path": "src/index.js",
      "sha256": "8f69e239e7365811abad1130954bb9d4772c0f0e31c477f37f22a3644de78652",
      "before": "const isHidden = function (node, displayCheck) {
  if (getComputedStyle(node).visibility === 'hidden') {
    return true;
  }

  const isDirectSummary = matches.call(node, 'details>summary:first-of-type');
  const nodeUnderDetails = isDirectSummary ? node.parentElement : node;
  if (matches.call(nodeUnderDetails, 'details:not([open]) *')) {
    return true;
  }",
      "after": "const isHidden = function (node, displayCheck) {
  if (getComputedStyle(node).visibility === 'hidden') {
    return true;
  }

  const isDirectSummary = matches.call(node, 'details>summary:first-child');
  const nodeUnderDetails = isDirectSummary ? node.parentElement : node;
  if (matches.call(nodeUnderDetails, 'details:not([open]) *')) {
    return true;
  }"
    }
  ],
  "expected_accessibility_effect": "Keyboard users can open the address dialog and have focus automatically move to the first focusable field (street address), satisfying WCAG 2.1.1 (Keyboard) and 2.4.3 (Focus Order).",
  "functional_risks": [
    "Minimal risk: the change only corrects an invalid CSS selector. The tabbable library may have relied on the invalid selector for some edge case, but 'details>summary:first-child' is the standard selector for the summary element."
  ],
  "verification_requirements": [
    "Run the frozen journey to confirm focus moves to #street after opening the dialog.",
    "Verify that the dialog still traps focus correctly (Tab cycles within dialog, Escape closes).",
    "Ensure no regression in other focus trap behaviors."
  ]
}
